+            <main class="page" id="main">
+              ${ImagePreview({ item: image })}
+            </main>
+            <footer class="site-footer">Private image library</footer>
+            ${DeleteDialog({ item: image })}
+          </div>
+        `;
+      }
+
+      function mountApp() {
+        const root = document.querySelector("#root");
+        root.innerHTML = App();
+
+        const dialog = document.querySelector("[data-delete-dialog]");
+        const openButton = document.querySelector("[data-open-dialog]");
+        const cancelButton = document.querySelector("[data-cancel-delete]");
+        const confirmButton = document.querySelector("[data-confirm-delete]");
+        const statusMessage = document.querySelector("[data-status]");
+
+        openButton.addEventListener("click", () => {
+          dialog.showModal();
+          cancelButton.focus();
+        });
+
+        cancelButton.addEventListener("click", () => {
+          dialog.close("cancel");
+        });
+
+        confirmButton.addEventListener("click", () => {
+          dialog.close("delete");
+          statusMessage.textContent = `${image.title} was deleted from your library.`;
+        });
+
+        dialog.addEventListener("close", () => {
+          openButton.focus();
+        });
+      }
+
